function renderObjects(){draw.clearLayers();handles.clearLayers();objectPaths.clear();for(const layer of state.layers){if(!layer.visible)continue;for(const o of layer.objects){const alpha=layer.opacity??1,style={pane:o.type==='point'?'userPointPane':'userPane',color:layer.color||o.color,opacity:alpha,weight:o.id===selected?4:2,fillColor:layer.color||o.color,fillOpacity:(o.type==='point'?.9:.1)*alpha,bubblingMouseEvents:false};const geometry=o.type==='point'?L.circleMarker(o.points[0],{...style,radius:7,className:'user-point'}):o.type==='polygon'?L.polygon(o.points,style):L.polyline(o.points,style);geometry.addTo(draw).bindTooltip(o.name+(o.measureDistance?' · '+formatDistance(o.points.reduce((n,p,i)=>i?n+distance(o.points[i-1],p):n,0)):''),{permanent:o.measureDistance===true||layer.names===true,opacity:layer.opacity??1});const element=geometry.getElement();if(element){element.setAttribute('aria-label',o.name);element.setAttribute('role','button');element.setAttribute('data-object-id',o.id)}geometry.on('click',e=>{L.DomEvent.stopPropagation(e);if(tool==='erase')eraseObject(o.id);else if(tool==='pan')inspectObject(o.id)});geometry.on('dblclick',e=>{L.DomEvent.stopPropagation(e);clearTimeout(clickTimer);if(tool==='erase')return;if(o.type==='polygon'){selectObject(o.id);openBox(o.points,o.name)}else selectObject(o.id)});objectPaths.set(o.id,geometry)}}}
