const hints={pan:'點選標記修訂；雙擊地圖可輸入區域座標。',point:'點選地圖放置標記；可與尺規同時使用。',line:'點選各頂點，再按上方 ✓ 完成線段。',polygon:'點選至少三個頂點，再按上方 ✓ 完成區域。',free:'按住地圖拖曳繪圖；尺規拖曳列之外可穿透繪畫。',erase:'點選自己的標記、線段或區域清除；可按復原還原。'};
function setTool(next){tool=next;map.getContainer().classList.toggle('erase-mode',next==='erase');document.body.classList.toggle('free-mode',next==='free');draftPoints=[];draft.clearLayers();handles.clearLayers();document.querySelectorAll('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===next));$('finish').hidden=!['line','polygon'].includes(next);$('hint').textContent=hints[next];$('drawing-status').textContent=({pan:'平移／選取',point:'標記',line:'線段',polygon:'區域',free:'自由繪圖',erase:'橡皮擦'}[next]);map.dragging[next==='free'?'disable':'enable']();map.getContainer().style.cursor=next==='pan'?'grab':'crosshair';if(next==='pan'&&getObject())showHandles(getObject().object)}
