map.on('click',e=>{if(tool==='pan'||tool==='free'||tool==='erase')return;clearTimeout(clickTimer);clickTimer=setTimeout(()=>{const p=[e.latlng.lat,e.latlng.lng,0];if(tool==='point')addObject('point',[p]);else{draftPoints.push(p);redrawDraft()}},200)});
map.on('dblclick',e=>{clearTimeout(clickTimer);if(tool==='pan')openBox([[e.latlng.lat,e.latlng.lng,0]],'座標外框')});
