const mapElement=map.getContainer();mapElement.addEventListener('pointerdown',e=>{if(tool!=='free'||e.target.closest('button,a,input,select')||e.button!==0)return;freePointer=e.pointerId;draftPoints=[];mapElement.setPointerCapture(e.pointerId);const bounds=mapElement.getBoundingClientRect(),p=map.containerPointToLatLng(snapDrawing([e.clientX-bounds.left,e.clientY-bounds.top]));draftPoints.push([p.lat,p.lng,0]);e.preventDefault()});
