document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='Escape'){$('instrument-menu').hidden=true;setTool('pan')}if(e.key==='Enter'&&!$('finish').hidden)finishDrawing();if((e.ctrlKey||e.metaKey)&&e.key==='z'&&!e.shiftKey){e.preventDefault();$('undo').click()}});
