function coordinateAction(mark){try{const p=[parseCoordinate($('latitude').value,true),parseCoordinate($('longitude').value,false),0];setTool('pan');map.setView(p,9);lastCursor=p;updateCursor();if(mark)selectObject(addObject('point',[p],$('point-name').value.trim()||undefined).id);else L.circleMarker(p,{radius:9,color:state.settings.color,fillOpacity:.2,interactive:false}).addTo(draft);$('coordinate-feedback').textContent=(mark?'已新增：':'已定位：')+pair(p)}catch(e){$('coordinate-feedback').textContent=e.message}};
$('coordinate-form').onsubmit=e=>{e.preventDefault();coordinateAction(true)};$('locate-coordinate').onclick=()=>coordinateAction(false);
function showPointPopup(name,p,source){const node=document.createElement('div'),title=document.createElement('b'),coords=document.createElement('p');title.textContent=name;coords.textContent=pair(p);node.append(title,coords);if(source){const a=document.createElement('a');a.textContent='資料來源 ↗';a.href=source;a.target='_blank';a.rel='noopener';node.append(a)}return node}
function selectedRouteNames(){return new Set(state.settings.selectedRoutes===null?routes.map(r=>r.name):state.settings.selectedRoutes)}
function renderRoutes(){routeLines.clearLayers();fixes.clearLayers();routePaths.clear();const selectedNames=selectedRouteNames(),seen=new Set();for(const r of routes){if(!selectedNames.has(r.name))continue;const points=r.points.map(p=>[p.lat,p.lng,0]);if(state.settings.routes){const routeStyle=state.settings.routeStyles?.[r.name]||{};const line=L.polyline(points,{pane:'routePane',color:r.name.includes('TRANSITION')?'#7ba6cf':'#6ed7bd',weight:1.7,opacity:.7,bubblingMouseEvents:false}).bindPopup(showPointPopup(r.name,points[0],r.source)).addTo(routeLines);line.on('click',()=>{openPanel('routes-panel');const row=[...$('route-list').children].find(x=>x.dataset.name===r.name);if(row){row.querySelector('details').open=true;row.scrollIntoView({block:'nearest'})}});routePaths.set(r.name,line);line.setStyle({color:routeStyle.color||state.settings.routeColor||'#6ed7bd',opacity:routeStyle.opacity??state.settings.routeOpacity??1});if(routeStyle.names)line.bindTooltip(r.name,{permanent:true})}if(state.settings.fixes)r.points.forEach(p=>{const key=p.name+p.lat+p.lng;if(seen.has(key))return;seen.add(key);const ll=[p.lat,p.lng,0];L.circleMarker(ll,{radius:3,color:'#8de4ce',weight:1,fillColor:'#163642',fillOpacity:1,bubblingMouseEvents:false}).bindTooltip(p.name,{permanent:state.settings.routeNames!==false,direction:'right',offset:[4,0]}).bindPopup(showPointPopup(p.name,ll,r.source)).addTo(fixes)})}$('route-count').textContent=selectedNames.size+'/'+routes.length;$('route-selection').textContent=`已選 ${selectedNames.size} / ${routes.length} 條航路`;waypointPicker.renderMap();applyRouteOpacity()}
