const gestures=new Map();
for(const name of ['ruler','protractor']){const el=$(name),pointers=new Map();let baseline=null;const begin=()=>{const ps=[...pointers.values()],s=state.instruments[name];if(ps.length===1)baseline={p:ps[0],x:s.x,y:s.y,rotation:s.rotation};else if(ps.length>=2)baseline={mid:{x:(ps[0].x+ps[1].x)/2,y:(ps[0].y+ps[1].y)/2},distance:Math.hypot(ps[1].x-ps[0].x,ps[1].y-ps[0].y),scale:s.scale||1,angle:gestureAngle(ps[0],ps[1]),x:s.x,y:s.y,rotation:s.rotation}};
 el.addEventListener('pointerdown',e=>{if(tool==='free'&&!e.target.closest('[data-instrument]')||e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();e.stopPropagation();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});el.setPointerCapture(e.pointerId);gestures.set(name,true);begin()});
 el.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!baseline)return;e.preventDefault();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const ps=[...pointers.values()],size=map.getSize(),s=state.instruments[name];if(ps.length>=2&&baseline.mid){const mid={x:(ps[0].x+ps[1].x)/2,y:(ps[0].y+ps[1].y)/2};s.x=Math.max(0,Math.min(1,baseline.x+(mid.x-baseline.mid.x)/size.x));s.y=Math.max(0,Math.min(.88,baseline.y+(mid.y-baseline.mid.y)/size.y));s.rotation=baseline.rotation+angleDelta(gestureAngle(ps[0],ps[1]),baseline.angle);s.scale=Math.max(.2,Math.min(3,baseline.scale*Math.hypot(ps[1].x-ps[0].x,ps[1].y-ps[0].y)/Math.max(1,baseline.distance)))}else if(ps.length===1&&baseline.p){if(e.shiftKey){s.rotation=baseline.rotation+(e.clientX-baseline.p.x)/2}else{s.x=Math.max(0,Math.min(1,baseline.x+(e.clientX-baseline.p.x)/size.x));s.y=Math.max(0,Math.min(.88,baseline.y+(e.clientY-baseline.p.y)/size.y))}}renderInstruments();updateInstrumentControls()});
 const end=e=>{pointers.delete(e.pointerId);if(!pointers.size){baseline=null;gestures.delete(name);if(name==='protractor')snapProtractor();else snapRuler();save()}else begin()};el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('dblclick',e=>{if(e.target.closest('[data-instrument]')){e.preventDefault();openPanel('ruler-panel')}});
}
