function clampOpacity(v){return Number.isFinite(v)?Math.max(0,Math.min(1,v)):1}
function opacityControl(name,value,apply){const b=document.createElement('button');b.className='opacity-button';let current=clampOpacity(value);const paint=()=>{b.textContent='透明度 '+Math.round(current*100)+'%';b.title='100% → 75% → 25% 循環（數值為可見度）';b.setAttribute('aria-label',name+' 透明度 '+Math.round(current*100)+'%')};paint();b.onclick=()=>{current=current===1?.75:current===.75?.25:1;apply(current);paint()};return b}
function layerStyle(layer,apply){const row=document.createElement('div');row.className='row';const names=document.createElement('button');const update=()=>names.textContent=layer.names?'隱藏名稱':'顯示名稱';update();names.onclick=()=>{snapshot();layer.names=!layer.names;update();apply()};const color=document.createElement('input');color.type='color';color.value=layer.color||'#75dfc8';color.setAttribute('aria-label','圖層顏色 '+(layer.name||''));color.onchange=()=>{snapshot();layer.color=color.value;apply()};row.append(names,color);return row}
function applyBasemapOpacity(){const alpha=clampOpacity(state.settings.baseOpacity);street.setOpacity(alpha);satellite.setOpacity(alpha);land.eachLayer(l=>{l.setStyle?.({opacity:alpha,fillOpacity:.9*alpha})});street.bringToBack();satellite.bringToBack()}
function applyRouteOpacity(){routeLines.eachLayer(l=>{const name=[...routePaths].find(([,v])=>v===l)?.[0],prefs=state.settings.routeStyles?.[name]||{};l.setStyle({opacity:clampOpacity(state.settings.routeOpacity)*(prefs.opacity??1),color:prefs.color||state.settings.routeColor||'#6ed7bd'});if(state.settings.routeNames)l.bindTooltip(l.getPopup()?.getContent()?.querySelector('b')?.textContent||'',{permanent:true})});fixes.eachLayer(l=>l.setStyle?.({opacity:clampOpacity(state.settings.fixOpacity),fillOpacity:clampOpacity(state.settings.fixOpacity)}))}
function applyReferenceOpacity(){referenceGroup.eachLayer(l=>{const id=l.options.referenceId,ref=references.find(r=>r.id===id),prefs=state.settings.referenceStyles?.[id]||{};l.setStyle?.({opacity:clampOpacity(state.settings.referenceOpacity?.[id]),fillOpacity:(l instanceof L.CircleMarker?1:.025)*clampOpacity(state.settings.referenceOpacity?.[id]),color:prefs.color||ref?.color});l.unbindTooltip();if(l instanceof L.CircleMarker){const at=l.getLatLng(),i=ref.points.findIndex(p=>Math.abs(p[0]-at.lat)<1e-7&&Math.abs(p[1]-at.lng)<1e-7),name=ref.pointNames?.[i]||ref.name+' · 頂點 '+(i+1);l.bindTooltip(name,{permanent:prefs.names===true});const el=l.getElement();if(el){el.setAttribute('role','button');el.setAttribute('aria-label',name)}}else l.bindTooltip(ref.name,{permanent:prefs.names===true})})}
function updateOpacityInputs(){for(const [panel,key,label,apply] of [['basemap-panel','baseOpacity','底圖',applyBasemapOpacity],['routes-panel','routeOpacity','航路',applyRouteOpacity],['waypoints-panel','fixOpacity','航點',()=>waypointPicker.renderMap()]]){let mount=$(key+'-control');if(!mount){mount=document.createElement('div');mount.id=key+'-control';$(panel).querySelector('.section-body').prepend(mount)}mount.replaceChildren(opacityControl(label,state.settings[key],v=>{snapshot();state.settings[key]=v;apply();save()}));if(key!=='baseOpacity'){const setting={name:label,names:state.settings[key==='routeOpacity'?'routeNames':'fixNames']!==false,color:state.settings[key==='routeOpacity'?'routeColor':'fixColor']||'#75dfc8'};mount.append(layerStyle(setting,()=>{state.settings[key==='routeOpacity'?'routeNames':'fixNames']=setting.names;state.settings[key==='routeOpacity'?'routeColor':'fixColor']=setting.color;renderRoutes();waypointPicker.renderMap();save()}))}}for(const ref of references){const el=[...$('reference-list').children].find(n=>n.querySelector('label')?.textContent===ref.name);if(el&&!el.querySelector('.reference-style')){state.settings.referenceStyles||={};const prefs=state.settings.referenceStyles[ref.id]||={name:ref.name,names:false,color:ref.color};const row=layerStyle(prefs,()=>{applyReferenceOpacity();save()});row.classList.add('reference-style');el.append(row)}}}
function eraseObject(id){const f=getObject(id);if(!f)return;snapshot();f.layer.objects=f.layer.objects.filter(o=>o.id!==id);selected=null;inspected=null;$('editor-panel').hidden=true;map.closePopup();renderObjects();renderLayers();save('已清除，可按復原還原')}
function inspectObject(id){const f=getObject(id);if(!f)return;if(inspected===id){map.closePopup();selectObject(id);return}inspected=id;const content=showPointPopup(f.object.name,f.object.points[0]);const desc=document.createElement('p');desc.textContent=(f.object.description||'')+' · 高度 '+altitudeText(f.object.points[0][2]||0);content.append(desc);if(f.object.points.length>1)content.append(makePointsTable(f.object.points,f.object.name));const edit=document.createElement('button');edit.textContent='編輯詳細資料';edit.onclick=()=>{map.closePopup();selectObject(id)};content.append(edit);L.popup().setLatLng(f.object.points[0]).setContent(content).openOn(map)}
function deleteLayer(id){const l=state.layers.find(l=>l.id===id);if(!l)return;snapshot();state.layers=state.layers.filter(l=>l.id!==id);if(!state.layers.length)state.layers.push({id:uid(),name:'標繪圖層 1',visible:true,objects:[]});state.activeLayerId=state.layers[0].id;selected=null;$('editor-panel').hidden=true;renderLayers();renderObjects();save('已刪除圖層，可復原')}
$('delete-layer').onclick=()=>deleteLayer(state.activeLayerId);
