document.addEventListener('keydown',e=>{if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&(e.key==='y'||e.key==='Z')){e.preventDefault();$('redo').click()}});
function angleSector(from,to){const delta=(to-from+360)%360;if(!delta)return null;const a=rad(from),b=rad(to),r=118;return`M170 170 L${170+r*Math.sin(a)} ${170-r*Math.cos(a)} A${r} ${r} 0 ${delta>180?1:0} 1 ${170+r*Math.sin(b)} ${170-r*Math.cos(b)} Z`}
$('protractor-range-form').onsubmit=e=>{e.preventDefault();const from=Number($('angle-from').value),to=Number($('angle-to').value);if(!Number.isFinite(from)||!Number.isFinite(to)||from<0||to<0||from>360||to>360||from===to)return $('angle-range-feedback').textContent='角度需介於 0–360，起點與終點不可相同';snapshot();state.instruments.protractor.ranges.push({id:uid(),name:'角度範圍',visible:true,from,to,color:$('angle-color').value});toggleInstrument('protractor',true);drawProtractor();renderRangeLists();save('已新增角度標色範圍')};
$('angle-range-clear').onclick=()=>{snapshot();state.instruments.protractor.ranges=[];drawProtractor();renderRangeLists();save()};
function renderRangeLists(){for(const name of ['ruler','protractor']){const root=$(name+'-ranges');if(!root)continue;root.replaceChildren();const title=document.createElement('p');title.textContent=(name==='ruler'?'直尺':'量角器')+' 已儲存標色';root.append(title);for(const range of state.instruments[name]?.ranges||[]){const d=document.createElement('details'),summary=document.createElement('summary');summary.textContent=range.name+' · '+(name==='ruler'?formatDistance(range.fromM)+'–'+formatDistance(range.toM):range.from+'°–'+range.to+'°');d.append(summary);const show=document.createElement('input');show.type='checkbox';show.checked=range.visible!==false;show.onchange=()=>{snapshot();range.visible=show.checked;renderInstruments();drawProtractor();save()};const label=document.createElement('input');label.value=range.name;label.setAttribute('aria-label','標色名稱');const from=document.createElement('input'),to=document.createElement('input'),color=document.createElement('input');for(const input of [from,to]){input.type='number';input.step='any'}from.value=name==='ruler'?range.fromM/factor(state.settings.unit):range.from;to.value=name==='ruler'?range.toM/factor(state.settings.unit):range.to;from.setAttribute('aria-label','已儲存範圍起點');to.setAttribute('aria-label','已儲存範圍終點');color.type='color';color.value=range.color;const apply=document.createElement('button');apply.textContent='儲存修正';apply.onclick=()=>{const a=Number(from.value),b=Number(to.value);if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||(name==='ruler'?b<=a:b<0||a>360||b>360||a===b))return toast('範圍數值不正確');snapshot();range.name=label.value.trim()||'標色範圍';range.color=color.value;if(name==='ruler'){range.fromM=a*factor(state.settings.unit);range.toM=b*factor(state.settings.unit)}else{range.from=a;range.to=b}renderRangeLists();renderInstruments();drawProtractor();save('標色範圍已儲存')};const del=document.createElement('button');del.textContent='刪除範圍';del.onclick=()=>{snapshot();state.instruments[name].ranges=state.instruments[name].ranges.filter(r=>r!==range);renderRangeLists();renderInstruments();drawProtractor();save()};d.append(show,label,from,to,color,apply,del);root.append(d)}}}
