function snapProtractor(){const s=state.instruments.protractor,g=instrumentGeometry('protractor'),center=[g.cx,g.cy],angle=rad(s.rotation),tip=[g.cx+Math.sin(angle)*g.width/2,g.cy-Math.cos(angle)*g.width/2];let best=null;const candidates=[...routePaths.values(),...objectPaths.values()].filter(l=>l instanceof L.Polyline);for(const l of candidates){const flat=l.getLatLngs().flat(Infinity).filter(p=>p?.lat!==undefined);for(let i=1;i<flat.length;i++){const a=map.latLngToContainerPoint(flat[i-1]),b=map.latLngToContainerPoint(flat[i]),project=p=>{const dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p[0]-a.x)*dx+(p[1]-a.y)*dy)/(dx*dx+dy*dy||1)));return[a.x+t*dx,a.y+t*dy]};const near=project(tip),c=project(center),d=Math.hypot(tip[0]-near[0],tip[1]-near[1]),dc=Math.hypot(center[0]-c[0],center[1]-c[1]);if(d<18&&dc<25&&(!best||d+dc<best.score)){let rotation=Math.atan2(b.x-a.x,-(b.y-a.y))*180/Math.PI;if(Math.abs(angleDelta(rotation,s.rotation))>90)rotation+=180;best={score:d+dc,c,rotation}}}}if(best){s.x=best.c[0]/map.getSize().x;s.y=best.c[1]/map.getSize().y;s.rotation=best.rotation;renderInstruments();toast('量角器中心與 0° 線已貼齊直線')}}
function snapDrawing(p){let best=p,dist=17;for(const n of ['ruler','protractor']){if(!state.instruments[n].visible)continue;const g=instrumentGeometry(n),a=rad(-g.rotation),dx=p[0]-g.cx,dy=p[1]-g.cy,x=dx*Math.cos(a)-dy*Math.sin(a)+g.width/2,y=dx*Math.sin(a)+dy*Math.cos(a)+g.height/2;let q;if(n==='ruler'){const edge=Math.abs(y)<Math.abs(y-g.height)?0:g.height;q=instrumentPoint(g,Math.max(0,Math.min(g.width,x)),edge)}else{const angle=Math.atan2(p[1]-g.cy,p[0]-g.cx),r=g.width*166/340;q=[g.cx+r*Math.cos(angle),g.cy+r*Math.sin(angle)]}const d=Math.hypot(q[0]-p[0],q[1]-p[1]);if(d<dist){best=q;dist=d}}return best}
